WITH flattened_attrs AS (SELECT id, plan, effective_from, currency, tier_prices, discounts, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT currency, COUNT(CASE WHEN currency = 'THB' THEN 1 END) AS thb_count, ROUND(AVG(avg_tier_price), 2) AS avg_avg_tier_price, SUM(CASE WHEN plan = 'enterprise' THEN entry_price ELSE 0 END) AS enterprise_entry_price, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count, COUNT(*) FILTER (WHERE currency = 'THB') AS thb_rows FROM flattened_attrs GROUP BY 1
